/** 방의 두루마리 한 판입니다. 다시 엮을 때마다 version이 1씩 올라간 새 두루마리가 생긴다. */
package com.dandimate.durooduroo.scroll.domain;
import jakarta.persistence.*; import java.time.LocalDateTime; import java.util.UUID;
@Entity @Table(name="scrolls") public class Scroll { @Id private String id; @Column(nullable=false) private String roomId; @Column(nullable=false) private int version; @Lob @Column(nullable=false) private String body; @Column(nullable=false) private LocalDateTime createdAt; protected Scroll(){} private Scroll(String r,int v,String b){id=UUID.randomUUID().toString();roomId=r;version=v;body=b;createdAt=LocalDateTime.now();} public static Scroll create(String roomId,int version,String body){return new Scroll(roomId,version,body);} public String getId(){return id;} public String getRoomId(){return roomId;} public int getVersion(){return version;} public String getBody(){return body;} public LocalDateTime getCreatedAt(){return createdAt;} }
